import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"فترة تأسيس النظام التكافلي","description":"","frontmatter":{},"headers":[],"relativePath":"ar/73-共生体系建立期.md","filePath":"ar/73-共生体系建立期.md","lastUpdated":null}'),e={name:"ar/73-共生体系建立期.md"};function i(h,t,o,n,s,u){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="فترة-تأسيس-النظام-التكافلي" tabindex="-1">فترة تأسيس النظام التكافلي <a class="header-anchor" href="#فترة-تأسيس-النظام-التكافلي" aria-label="Permalink to &quot;فترة تأسيس النظام التكافلي&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>73</td></tr><tr><td>الوحدة</td><td>العصور التاريخية والأحداث الكبرى</td></tr><tr><td>الكلمات المفتاحية</td><td>النظام التكافلي، البناء المؤسسي، إعادة البناء الاجتماعي، تأسيس الواقع، القوانين الخمسة المساندة</td></tr></tbody></table><h2 id="أولاً-المهام-التاريخية-لفترة-تأسيس-النظام-التكافلي" tabindex="-1">أولاً: المهام التاريخية لفترة تأسيس النظام التكافلي <a class="header-anchor" href="#أولاً-المهام-التاريخية-لفترة-تأسيس-النظام-التكافلي" aria-label="Permalink to &quot;أولاً: المهام التاريخية لفترة تأسيس النظام التكافلي&quot;">​</a></h2><p>فترة تأسيس النظام التكافلي هي فترة البناء المؤسسي لحضارة التكافل المرساة، وتقابل مرحلة «تأسيس الواقع» في مسار الارتقاء البعدي بأربع مراحل. تبدأ هذه الحقبة بتوقيع الميثاق التكافلي وتنتهي بالفتح الشامل لأنظمة الزراعة الأصلية الثلاثمائة؛ ومهمتها التاريخية المحورية تحويل أحكام الميثاق المبدئية إلى مؤسسات اجتماعية قابلة للتشغيل، وإتمام النزول من «الفكرة» إلى «الواقع».</p><p>يمتد إطار هذه الفترة الزمني نحو عدة مئات من السنين. في هذه الفترة، أتمت الحضارة التكافلية بناءً مؤسسياً شاملاً يغطي النظام القانوني والمؤسسات الاجتماعية والتعليم والرعاية الصحية وضمانات السكن وآليات التوزيع الاقتصادي، واضعة أساساً اجتماعياً متيناً لتعميم الزراعة والاختراقات التكنولوجية لاحقاً.</p><h2 id="ثانياً-تأسيس-النظام-القانوني" tabindex="-1">ثانياً: تأسيس النظام القانوني <a class="header-anchor" href="#ثانياً-تأسيس-النظام-القانوني" aria-label="Permalink to &quot;ثانياً: تأسيس النظام القانوني&quot;">​</a></h2><p>كان تأسيس النظام القانوني المهمة الأولى لفترة تأسيس النظام التكافلي. اتخذت الحضارة التكافلية الدستور التكافلي قانوناً جوهرياً، وأقامت تدريجياً إطاراً قانونياً متكاملاً:</p><table tabindex="0"><thead><tr><th>المستوى القانوني</th><th>القانون المحوري</th><th>المضامين الرئيسية</th></tr></thead><tbody><tr><td>القانون الجوهري</td><td>الدستور التكافلي</td><td>يرسخ المؤسسات الجوهرية للحضارة والحقوق والواجبات الأساسية للمواطنين وإطار الحكم</td></tr><tr><td>القانون الأساسي</td><td>قانون العمل التكافلي</td><td>يحمي حقوق العمل، ويرسي مبدأ التوزيع «الأكثر عملاً الأكثر أجراً»</td></tr><tr><td>القانون الأساسي</td><td>قانون حماية المستهلك</td><td>يحمي الحقوق والمصالح المشروعة للحياة في الاستهلاك والخدمات</td></tr><tr><td>قانون الضمان</td><td>قانون ضمان التعليم</td><td>يرسخ التعليم الأساسي المجاني ونظام التعليم العالي المفتوح</td></tr><tr><td>قانون الضمان</td><td>قانون ضمان الرعاية الصحية</td><td>يرسخ نظام رعاية صحية مجانية شاملة وضمان صحة الزراعة</td></tr><tr><td>قانون الضمان</td><td>قانون ضمان السكن</td><td>يضمن لكل شكل من أشكال الحياة الحق الأساسي في السكن</td></tr><tr><td>قانون الضمان</td><td>قانون حماية البيئة</td><td>يرسخ نظام حماية البيئة والوقاية من التلوث الطاقي ومكافحته</td></tr><tr><td>القانون التنظيمي</td><td>قانون مكافحة الاحتكار</td><td>يحظر احتكار الزراعة واحتكار التكنولوجيا واحتكار الموارد</td></tr></tbody></table><p>يشكل هذا النظام القانوني «دستور واحد، وقانونان أساسيان، وخمسة قوانين ضمان، وقانون تنظيمي واحد» الهيكل المؤسسي للحضارة التكافلية. جسّدت عملية التشريع مبدأ «تقدم عشرة آلاف عرق معاً» تجسيداً كاملاً؛ فكان لكل الأعراق الرئيسية ممثلون يشاركون في التشريع، بما يضمن أن تراعي القوانين احتياجات أشكال الحياة المختلفة.</p><h2 id="ثالثاً-إعادة-بناء-المؤسسات-الاجتماعية" tabindex="-1">ثالثاً: إعادة بناء المؤسسات الاجتماعية <a class="header-anchor" href="#ثالثاً-إعادة-بناء-المؤسسات-الاجتماعية" aria-label="Permalink to &quot;ثالثاً: إعادة بناء المؤسسات الاجتماعية&quot;">​</a></h2><p>في الإطار القانوني، أعادت الحضارة التكافلية بناء المؤسسات الاجتماعية إعادة بناء شاملة:</p><h3 id="_3-1-إعادة-بناء-نظام-التعليم" tabindex="-1">3.1 إعادة بناء نظام التعليم <a class="header-anchor" href="#_3-1-إعادة-بناء-نظام-التعليم" aria-label="Permalink to &quot;3.1 إعادة بناء نظام التعليم&quot;">​</a></h3><ul><li>أُنشئ نظام تعليم مجاني من التمهيدي إلى العالي، وأُدرجت المعارف الأساسية لهندسة القوانين ضمن محتوى التعليم العام.</li><li>أُلغي نظام احتكار الأستاذ والتلميذ في طرق الزراعة، وحل محله شبكة مرشدين مفتوحة.</li><li>أُنشئت آلية تقييم تعليمي فردي، توصي بأنظمة زراعة مناسبة وفق خصائص كل شكل من أشكال الحياة.</li></ul><h3 id="_3-2-إعادة-بناء-النظام-الصحي" tabindex="-1">3.2 إعادة بناء النظام الصحي <a class="header-anchor" href="#_3-2-إعادة-بناء-النظام-الصحي" aria-label="Permalink to &quot;3.2 إعادة بناء النظام الصحي&quot;">​</a></h3><ul><li>أُنشئ نظام رعاية صحية مجانية شاملة، طُبقت فيه مكتسبات زراعة نظام دورة الحياة على علاج الأمراض.</li><li>أُنشئ نظام مراقبة صحة الزراعة، يراقب في الزمن الحقيقي الحالة الجسدية والنفسية للمزارعين، لوقاية من انحراف الزراعة.</li><li>أُنشئت إجراءات معالجة طبية وأخلاقية متخصصة للحياة الشاذة وكيانات الاستبدال المظلم.</li></ul><h3 id="_3-3-إعادة-بناء-السكن-والبيئة" tabindex="-1">3.3 إعادة بناء السكن والبيئة <a class="header-anchor" href="#_3-3-إعادة-بناء-السكن-والبيئة" aria-label="Permalink to &quot;3.3 إعادة بناء السكن والبيئة&quot;">​</a></h3><ul><li>أُنشئ نظام ضمان السكن الأساسي، يضمن لكل شكل من أشكال الحياة فضاء سكنياً آمناً ومريحاً.</li><li>استُخدمت تقنية تمديد الفضاء لتوسيع المساحات السكنية على الأراضي المحدودة، تخفيفاً للضغط السكاني.</li><li>أُنشئت آلية استعادة البيئة، تستخدم نظام دورة الحياة لإصلاح البيئة التي خربها عصر ما قبل المرساة.</li></ul><h3 id="_3-4-إعادة-بناء-التوزيع-الاقتصادي" tabindex="-1">3.4 إعادة بناء التوزيع الاقتصادي <a class="header-anchor" href="#_3-4-إعادة-بناء-التوزيع-الاقتصادي" aria-label="Permalink to &quot;3.4 إعادة بناء التوزيع الاقتصادي&quot;">​</a></h3><ul><li>أُنشئت آلية التعاقد المشترك على الإنتاج، توزع موارد الزراعة والموارد العامة توزيعاً عادلاً وفق المساهمة والحاجة.</li><li>أُلغي نظام توارث الموارد، وحُظر على أي منظمة أو فرد احتكار الموارد الرئيسية.</li><li>أُنشئ نظام توحيد وقياس الطاقة، يقدم أساساً تقنياً للتوزيع العادل.</li></ul><h2 id="رابعاً-ممارسة-الأنماط-الخمسة-للحضارة-التكافلية" tabindex="-1">رابعاً: ممارسة الأنماط الخمسة للحضارة التكافلية <a class="header-anchor" href="#رابعاً-ممارسة-الأنماط-الخمسة-للحضارة-التكافلية" aria-label="Permalink to &quot;رابعاً: ممارسة الأنماط الخمسة للحضارة التكافلية&quot;">​</a></h2><p>في مسار البناء المؤسسي، طورت الأبعاد والمناطق المختلفة خمسة أنماط للحضارة التكافلية وفق تاريخها وثقافتها وخصائصها العرقية:</p><table tabindex="0"><thead><tr><th>النمط</th><th>الخصائص المحورية</th><th>المناطق النموذجية</th></tr></thead><tbody><tr><td>النمط الكثيف لشرق آسيا</td><td>كثافة سكانية عالية، استغلال فعال للموارد، تقليد جماعي</td><td>منطقة استيطان رين زو الشرقية</td></tr><tr><td>النمط الرفاهي لشمال أوروبا</td><td>ضمانات رفاه عالية، حرية فردية، انسجام الإنسان والطبيعة</td><td>مناطق جينغلينغ زو (عرق الجان) في مناطق البرد القارس</td></tr><tr><td>النمط التعددي لأمريكا الشمالية</td><td>تعايش متعدد الأعراق، انفتاح ثقافي، قيادة الابتكار</td><td>المنطقة التعددية متعددة الأعراق في القارة الجديدة</td></tr><tr><td>النمط الاجتماعي لأوروبا القارية</td><td>اقتصاد سوق اجتماعي، استقلال القطاعات، موروث ثقافي</td><td>منطقة نهضة الحضارات العريقة</td></tr><tr><td>النمط اللاحق المتطور</td><td>تصنيع سريع، أولوية البنية التحتية، مجتمع متعلّم</td><td>المناطق المتأخرة في مناطق الافتراس السابقة</td></tr></tbody></table><p>الأنماط الخمسة ليست متبادلة النفي؛ بل هي ممارسات مؤسسية بتركيزات مختلفة تحت إطار الدستور التكافلي الموحد. وهي تحافظ فيما بينها على تبادل ومنافسة وثيقين، وتثري معاً المضامين المؤسسية للحضارة التكافلية.</p><h2 id="خامساً-البناء-الأولي-للبنية-التحتية-للمرساة" tabindex="-1">خامساً: البناء الأولي للبنية التحتية للمرساة <a class="header-anchor" href="#خامساً-البناء-الأولي-للبنية-التحتية-للمرساة" aria-label="Permalink to &quot;خامساً: البناء الأولي للبنية التحتية للمرساة&quot;">​</a></h2><p>كانت فترة تأسيس النظام التكافلي فترة بناء واسع النطاق للبنية التحتية للمرساة أيضاً:</p><ul><li>أُنجزت المرساة الرئيسية الكونية من المستوى الأول في بداية الحقبة، فأصبحت نواة شبكة مراسي الكون كله.</li><li>نُشرت المراسي الرئيسية للأبعاد من المستوى الثاني تباعاً في الأبعاد الرئيسية، وتشكلت أولياً قدرة تسيير الطاقة بمستوى الأبعاد.</li><li>غطت مراسي المناطق من المستوى الثالث المناطق الكثيفة السكان، داعمةً تعميم الزراعة بالطاقة.</li><li>بدأت مراسي المجتمع من المستوى الرابع نشراً تجريبياً، لتجميع الخبرة للتغطية الشاملة اللاحقة.</li></ul><p>يتبع بناء البنية التحتية للمرساة مبدأ «تخطيط موحد وبناء متدرج»، بما يضمن الاستغلال الفعال للموارد وعدالة التغطية.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>فترة تأسيس النظام التكافلي هي «عصر إرساء الأسس» لحضارة التكافل المرساة. لقد أتمت في بضعة قرون التحول المؤسسي الجوهري من النظام الافتراسي لعصر ما قبل المرساة إلى النظام التكافلي. أعطى تأسيس النظام القانوني الحضارة إطاراً من القواعد؛ وأعطتها إعادة بناء المؤسسات الاجتماعية ضمانات واقعية لجميع الكائنات؛ وأعطتها ممارسة الأنماط الخمسة مسارات تعددة للابتكار المؤسسي؛ وأرسى بناء البنية التحتية للمرساة الأساس المادي للتطور اللاحق. وحين جاءت لحظة الفتح الشامل لأنظمة الزراعة الأصلية الثلاثمائة، كانت الحضارة التكافلية مستعدة مؤسسياً تماماً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>72-锚点觉醒纪元 (عصر صحوة المرساة)</li><li>74-三百套体系开放事件 (حدث فتح أنظمة الثلاثمائة)</li><li>40-共生宪法总纲 (الخطوط العامة للدستور التكافلي)</li></ul>',31)])])}const c=a(e,[["render",i]]);export{_ as __pageData,c as default};
